using System.Threading.Tasks;
using Xunit;

namespace silkgltriangle.Tests;

/// <summary>
/// <see cref="WorldgenStats"/> is process-global and every chunk generated by any test feeds it,
/// so these run in the non-parallel "Worldgen seed" collection, where nothing else generates
/// terrain at the same time.
/// </summary>
[Collection("Worldgen seed")]
public sealed class WorldgenStatsTests
{
    [Fact]
    public void TakeWindowReturnsWhatWasAddedSinceThePreviousTakeAndKeepsTheTotals()
    {
        WorldgenStats.TakeWindow(out _, out _, out _, out _, out _);
        var totalChunksBefore = WorldgenStats.TotalChunks;
        var totalGenBefore = WorldgenStats.TotalGenTicks;
        var totalTreeBefore = WorldgenStats.TotalTreeTicks;

        const int perThread = 1000;
        Parallel.For(0, 2, _ =>
        {
            for (var i = 0; i < perThread; i++)
            {
                WorldgenStats.AddChunk(3);
                WorldgenStats.AddTreeTicks(2);
            }
        });

        WorldgenStats.TakeWindow(out var treeTicks, out var genTicks, out var chunks, out _, out _);
        Assert.Equal(2 * perThread, chunks);
        Assert.Equal(2 * perThread * 3L, genTicks);
        Assert.Equal(2 * perThread * 2L, treeTicks);

        // The take zeroed the window...
        WorldgenStats.TakeWindow(out treeTicks, out genTicks, out chunks, out _, out _);
        Assert.Equal(0, chunks);
        Assert.Equal(0, genTicks);
        Assert.Equal(0, treeTicks);

        // ...while the lifetime totals kept everything
        Assert.Equal(totalChunksBefore + 2 * perThread, WorldgenStats.TotalChunks);
        Assert.Equal(totalGenBefore + 2 * perThread * 3L, WorldgenStats.TotalGenTicks);
        Assert.Equal(totalTreeBefore + 2 * perThread * 2L, WorldgenStats.TotalTreeTicks);

        // A later add starts the next window from zero
        WorldgenStats.AddChunk(5);
        WorldgenStats.TakeWindow(out _, out genTicks, out chunks, out _, out _);
        Assert.Equal(1, chunks);
        Assert.Equal(5, genTicks);
    }

    [Fact]
    public void GrowsAreAccountedApartFromTheTreeStamp()
    {
        WorldgenStats.TakeWindow(out _, out _, out _, out _, out _);
        var totalGrowsBefore = WorldgenStats.TotalGrows;
        var totalGrowTicksBefore = WorldgenStats.TotalGrowTicks;
        var totalTreeBefore = WorldgenStats.TotalTreeTicks;

        WorldgenStats.AddGrow(7);
        WorldgenStats.AddGrow(11);

        WorldgenStats.TakeWindow(out var treeTicks, out var genTicks, out var chunks,
            out var growTicks, out var grows);
        Assert.Equal(2, grows);
        Assert.Equal(18, growTicks);
        Assert.Equal(0, treeTicks);
        Assert.Equal(0, genTicks);
        Assert.Equal(0, chunks);
        Assert.Equal(totalGrowsBefore + 2, WorldgenStats.TotalGrows);
        Assert.Equal(totalGrowTicksBefore + 18, WorldgenStats.TotalGrowTicks);
        Assert.Equal(totalTreeBefore, WorldgenStats.TotalTreeTicks);

        WorldgenStats.AddTreeTicks(4);
        WorldgenStats.TakeWindow(out treeTicks, out _, out _, out growTicks, out grows);
        Assert.Equal(4, treeTicks);
        Assert.Equal(0, growTicks);
        Assert.Equal(0, grows);
    }
}
